import 'package:go_router/go_router.dart';import 'package:flutter/material.dart';import '../../services/demo_store.dart';import '../../widgets/party_card.dart';
class DiscoverScreen extends StatefulWidget{const DiscoverScreen({super.key});@override State<DiscoverScreen>createState()=>_DiscoverScreenState();}class _DiscoverScreenState extends State<DiscoverScreen>{String q='';final s=DemoStore.instance;@override Widget build(BuildContext c){s.init();final list=s.parties.where((p)=>q.isEmpty||p.title.toLowerCase().contains(q.toLowerCase())||(p.category??'').contains(q.toLowerCase())).toList();return SafeArea(child:Column(children:[Padding(padding:const EdgeInsets.all(16),child:TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search themes, people, categories',border:OutlineInputBorder()),onChanged:(v)=>setState(()=>q=v))),Expanded(child:ListView.builder(padding:const EdgeInsets.symmetric(horizontal:16),itemCount:list.length,itemBuilder:(_,i)=>Padding(padding:const EdgeInsets.only(bottom:12),child:PartyCard(party:list[i],onTap:()=>GoRouter.of(c).push('/party/${list[i].id}'))))) ]));}}
